# Problem: #2897 Apply Operations on Array to Maximize Sum of Squares
# Language: python3
# Submission Result: Submission Sent (Check LeetCode Profile)
# Auto-generated by LeetCode Agent

class Solution:
    def maxSum(self, nums: List[int], k: int) -> int:
        length = len(nums)
        bit_counts = [0] * 32
        reconstructed_numbers = [0] * length
        
        for number in nums:
            for bit_index in range(32):
                if (number >> bit_index) & 1:
                    reconstructed_numbers[bit_counts[bit_index]] += 1 << bit_index
                    bit_counts[bit_index] += 1
    
        total_sum = 0 
        modulo = 10**9 + 7
        
        for index in range(k):
            total_sum += reconstructed_numbers[index] ** 2
            total_sum %= modulo 
            
        return total_sum